create schema if not exists aiops;
create table if not exists aiops.schema_migrations(version text primary key, applied_at timestamptz not null default now());
create table if not exists aiops.runs(run_id text primary key,incident_id text,mode text not null check(mode in('LIVE','DEMO','REPLAY','STORY')),scenario_id text not null,status text not null check(status in('CREATED','RUNNING','WAITING','BLOCKED','RESOLVED','FAILED','CANCELLED')),version bigint not null default 1,idempotency_key text not null unique,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,overall_confidence numeric not null default 0 check(overall_confidence between 0 and 1));
create table if not exists aiops.run_events(event_id text primary key,run_id text not null references aiops.runs(run_id),sequence bigint not null,stage text not null,event_type text not null,status text not null,occurred_at timestamptz not null default now(),evidence_ids jsonb not null default '[]',decision text,confidence numeric check(confidence between 0 and 1),payload jsonb not null default '{}',unique(run_id,sequence));
create table if not exists aiops.evidence(evidence_id text primary key,source text not null,external_id text,observed_at timestamptz,known_at timestamptz not null default now(),claim text not null,confidence numeric not null check(confidence between 0 and 1),provenance jsonb not null default '{}',payload_hash text not null,payload jsonb not null default '{}');
create table if not exists aiops.gates(gate_id text primary key,run_id text not null references aiops.runs(run_id),stage text not null,state text not null check(state in('PASS','FAIL','BLOCKED','UNKNOWN')),required_evidence jsonb not null default '[]',evidence_ids jsonb not null default '[]',decision text,reason text,evaluated_at timestamptz not null default now(),unique(run_id,stage));
create table if not exists aiops.twin_nodes(node_id text primary key,type text not null,name text not null,site text,state text not null default 'UNKNOWN',criticality smallint not null default 3 check(criticality between 1 and 5),health numeric check(health between 0 and 1),confidence numeric check(confidence between 0 and 1),valid_from timestamptz,valid_to timestamptz,known_at timestamptz not null default now());
create table if not exists aiops.twin_edges(edge_id text primary key,source_id text not null references aiops.twin_nodes(node_id),target_id text not null references aiops.twin_nodes(node_id),relation_type text not null,redundancy smallint not null default 1 check(redundancy>=1),confidence numeric not null check(confidence between 0 and 1),valid_from timestamptz,valid_to timestamptz,known_at timestamptz not null default now(),unique(source_id,target_id,relation_type));
create table if not exists aiops.scenarios(scenario_id text primary key,name text not null,seed bigint not null,synthetic boolean not null default true,description text,created_at timestamptz not null default now());
create table if not exists aiops.command_receipts(receipt_id text primary key,run_id text not null references aiops.runs(run_id),idempotency_key text not null unique,command text not null,response jsonb not null,created_at timestamptz not null default now());
create index if not exists ix_runs_status on aiops.runs(status); create index if not exists ix_events_run on aiops.run_events(run_id,sequence); create index if not exists ix_nodes_type_state on aiops.twin_nodes(type,state);
